// v3.52.0 CARD 298 - SNAPSHOT IDENTITY IS ESTABLISHED AT WRITE TIME, NOT REPAIRED AFTERWARDS.
// Every snapshot INSERT now routes through here, so no writer can create a row whose identity
// has to be backfilled later. It reuses the existing helpers rather than copying hash logic:
// snapshotHashEnsure guarantees the column exists, patchSha computes the digest. A caller that
// has ALREADY computed the hash - snapshotWorker needs it for its dedupe decision before the
// row is written - passes it as shaOpt so the digest is never taken twice. The D1 run() result
// is returned unchanged so callers reading meta.last_row_id keep working.
// SEMANTICS PRESERVED DELIBERATELY: size is still patchByteLen(code || ""), and code is still
// bound as given, exactly as every call site did before. This hunk adds the hash and changes
// nothing else. LEGACY ROWS ARE NOT TOUCHED - /snapshot-hash-backfill remains the cleanup lane
// for rows written before this change, per the card 298 fence.
async function snapshotInsert(env, name, acctId, code, mainModule, source, shaOpt) {
  await snapshotHashEnsure(env);
  const sha = shaOpt || await patchSha(code || "");
  return await env.DB.prepare(
    "INSERT INTO snapshots (worker_name, account_id, code, main_module, size, source, code_sha256) VALUES (?,?,?,?,?,?,?)"
  ).bind(name, acctId, code, mainModule, patchByteLen(code || ""), source, sha).run();
}

